<?php use App\Core\Crm; ?>
<div class="page-head"><div><h1>Abonați newsletter</h1><p>Abonații sunt contacte din CRM cu acord de marketing. Formularul din subsolul site-ului folosește confirmare prin email (double opt-in).</p></div>
<div class="actions"><a class="btn" href="<?= e(url('/admin/crm/contacte?newsletter=subscribed')) ?>">Toți abonații în CRM</a><a class="btn" href="<?= e(url('/admin/crm/export?newsletter=subscribed')) ?>"><?= icon('download') ?> Export</a><a class="btn" href="<?= e(url('/admin/crm/import')) ?>"><?= icon('upload') ?> Import</a></div></div>
<div class="grid g4"><?php foreach ($counts as $k => $n): ?><a class="card kpi" href="<?= e(url('/admin/crm/contacte?newsletter=' . $k)) ?>" style="text-decoration:none;color:inherit"><small><?= e(Crm::NEWSLETTER[$k]) ?></small><b><?= $n ?></b></a><?php endforeach; ?></div>
<div class="table-wrap" style="margin-top:16px"><table class="t"><thead><tr><th>Contact</th><th>Status</th><th>Acord / dezabonare</th><th>Sursă</th></tr></thead><tbody>
<?php foreach ($recent as $r): ?><tr><td><a href="<?= e(url('/admin/crm/contacte/' . $r['id'])) ?>"><?= e($r['name']) ?></a><div class="small muted"><?= e($r['email']) ?></div></td><td><span class="badge <?= $r['newsletter'] === 'subscribed' ? 'b-ok' : ($r['newsletter'] === 'pending' ? 'b-warn' : 'b-err') ?>"><?= e(Crm::NEWSLETTER[$r['newsletter']]) ?></span></td><td class="small muted"><?= e(local_time($r['newsletter_consent_at'] ?: $r['unsubscribed_at'])) ?></td><td class="small"><?= e(Crm::sourceLabel($r['source'])) ?></td></tr><?php endforeach; ?>
<?php if (!$recent): ?><tr><td colspan="4" class="empty">Niciun abonat încă. Formularul de newsletter din subsolul site-ului începe să colecteze abonați imediat.</td></tr><?php endif; ?>
</tbody></table></div>
